using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Globalization;
using System.Collections.Generic;
using System.Reflection;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
internal sealed class DofusGuideChoice {public string Title{get;set;}public string Slug{get;set;}public ImageSource Icon{get;set;}public override string ToString(){return Title;}}
internal static class DofusVisuals {
 static readonly string[] names={"dofus-argente-scintillant","dofus-des-veilleurs","dofus-du-cauchemar","dofus-des-glaces","dofus-forgelave","dofus-sylvestre","dofus-turquoise","dofus-emeraude","dofus-nebuleux","dofus-abyssal","dofus-tachete","dofus-kaliptus","dofus-pourpre","dofus-cawotte","dofus-argente","dofus-ivoire","dofus-cacao","dofus-vulbis","dofus-ebene","dofus-ocre","dom-de-pin","dolmanax","domakuro","dorigami","dofoozbz","dofawa","dokille","dokoko","dotruche","jyfus"};
 static readonly Dictionary<string,BitmapSource> icons=new Dictionary<string,BitmapSource>();
 static string Key(string s){return new string((s??"").Normalize(NormalizationForm.FormD).Where(c=>CharUnicodeInfo.GetUnicodeCategory(c)!=UnicodeCategory.NonSpacingMark&&Char.IsLetterOrDigit(c)).ToArray()).ToLowerInvariant();}
 internal static BitmapSource Icon(string slug,string title){string key=Key(slug+" "+title),name=names.FirstOrDefault(n=>key.Contains(Key(n.Replace("dofus-",""))));if(name==null)return null;BitmapSource image;if(icons.TryGetValue(name,out image))return image;using(var input=Assembly.GetExecutingAssembly().GetManifestResourceStream("MonEspace.Dofus."+name+".png")){if(input==null)return null;var bitmap=new BitmapImage();bitmap.BeginInit();bitmap.CacheOption=BitmapCacheOption.OnLoad;bitmap.StreamSource=input;bitmap.EndInit();bitmap.Freeze();icons[name]=bitmap;return bitmap;}}
 internal static DataTemplate Template(){var dock=new FrameworkElementFactory(typeof(DockPanel));var image=new FrameworkElementFactory(typeof(Image));image.SetValue(Image.WidthProperty,32.0);image.SetValue(Image.HeightProperty,32.0);image.SetValue(FrameworkElement.MarginProperty,new Thickness(0,0,10,0));image.SetBinding(Image.SourceProperty,new System.Windows.Data.Binding("Icon"));dock.AppendChild(image);var title=new FrameworkElementFactory(typeof(TextBlock));title.SetBinding(TextBlock.TextProperty,new System.Windows.Data.Binding("Title"));title.SetValue(FrameworkElement.VerticalAlignmentProperty,VerticalAlignment.Center);title.SetValue(TextBlock.TextWrappingProperty,TextWrapping.Wrap);dock.AppendChild(title);return new DataTemplate{VisualTree=dock};}
 internal static Border Header(Store store,DofusCharacter c,TougliDocument doc,bool compact,Brush ink,Brush muted,Brush accent,Brush surface,Brush line){var options=store.Value.dofus.overlay;var layout=new StackPanel();var row=new Grid();row.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(options.showPortrait?(compact?options.portrait+8:130):0)});row.ColumnDefinitions.Add(new ColumnDefinition());row.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(options.showDofus?(compact?options.dofus+10:108):0)});var portrait=CharacterPortraits.FullView(store,c,compact?options.portrait:116,compact?(int)(options.portrait*1.35):150,line,surface,accent);portrait.Visibility=options.showPortrait?Visibility.Visible:Visibility.Collapsed;row.Children.Add(portrait);var identity=new StackPanel{VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(4,0,8,0)};identity.Children.Add(Text(c.name,compact?15:22,ink));if(!String.IsNullOrEmpty(c.server))identity.Children.Add(Text(c.server,11,muted));identity.Children.Add(Text(doc==null?"Choisissez votre parcours":doc.Title,compact?11:14,muted));Grid.SetColumn(identity,1);row.Children.Add(identity);string title=doc==null?c.guide:doc.Title;var icon=Icon(c.guide,title);var reward=new StackPanel{VerticalAlignment=VerticalAlignment.Center};reward.Children.Add(Text(icon==null?"PARCOURS":"DOFUS EN COURS",8,muted));if(icon!=null)reward.Children.Add(new Image{Source=icon,Width=compact?options.dofus:92,Height=compact?options.dofus:92,Stretch=Stretch.Uniform,Margin=new Thickness(0,6,0,0),ToolTip=title});reward.Visibility=options.showDofus?Visibility.Visible:Visibility.Collapsed;Grid.SetColumn(reward,2);row.Children.Add(reward);layout.Children.Add(row);if(doc!=null&&options.showProgress){var progress=DofusCompanion.Find(store.Value,c);int done=doc.Steps.Count(s=>progress!=null&&progress.done.Contains(s.Key));layout.Children.Add(Text(done+" / "+doc.Steps.Count+" étapes validées · "+Math.Round(100.0*done/doc.Steps.Count)+" %",11,accent));layout.Children.Add(new ProgressBar{Minimum=0,Maximum=Math.Max(1,doc.Steps.Count),Value=done,Height=6,Foreground=accent,Background=line,Margin=new Thickness(0,7,0,0)});}return new Border{Child=layout,Padding=new Thickness(compact?13:18),CornerRadius=new CornerRadius(14),Background=surface,BorderBrush=line,BorderThickness=new Thickness(1),Margin=new Thickness(0,0,0,14)};}
 static TextBlock Text(string text,double size,Brush ink){return new TextBlock{Text=text,FontSize=size,Foreground=ink,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,4,0,5)};}
}
